//#region src/StreamChannel.ts
var StreamChannel = class extends ChannelApi {
	get cid() {
		return `${this.type}:${this.id}`;
	}
	getOrCreate = (channel_get_or_create_request) => {
		if (!this.id) return this.chatApi.getOrCreateDistinctChannel({
			type: this.type,
			...channel_get_or_create_request
		}).then((response) => {
			this.id = response.channel?.id;
			return response;
		});
		else return this.chatApi.getOrCreateChannel({
			id: this.id,
			type: this.type,
			...channel_get_or_create_request
		});
	};
	queryMembers(request) {
		return this.chatApi.queryMembers({ payload: {
			id: this.id,
			type: this.type,
			...request?.payload ?? { filter_conditions: {} }
		} });
	}
};
//#endregion
//#region src/StreamChatClient.ts
var StreamChatClient = class extends ChatApi {
	channel = (type, id) => {
		return new StreamChannel(this, type, id);
	};
};
